<script setup lang="ts">
/**
 * A segmented month-and-year field with no popup (`design/components/month-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/month-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import {
  agentMember,
  agentMonth,
  eraseSegment,
  fieldSegments,
  monthDraft,
  monthFieldValue,
  monthOutOfBounds,
  segmentValueText,
  stepSegment,
  typeIntoSegment,
} from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/month-input.module.css'

export interface MonthInputMessages {
  empty: string
}

export interface MonthInputProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  defaultValue?: string | null
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * Sets the segment order, the separator and the month's name.
   */
  locale?: string
  /**
   * The last month the field accepts, as `YYYY-MM`. A later month marks the field invalid.
   */
  max?: string
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  messages?: MonthInputMessages
  /**
   * The first month the field accepts, as `YYYY-MM`. An earlier month marks the field invalid.
   */
  min?: string
  /**
   * Serializes the month as `YYYY-MM`, as `<input type="month">` does.
   */
  name?: string
  /**
   * Keeps segments focusable, but arrows and digits do not edit.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * A month as `YYYY-MM`, the form `<input type="month">` reports, or `null` while a segment is
   * empty. Text that is not a month shows as empty.
   */
  value?: string | null
}

defineOptions({ name: 'MonthInput', inheritAttrs: false, controlKind: 'group' })

const props = withDefaults(defineProps<MonthInputProps>(), {
  ariaRequired: undefined,
  disabled: false,
  invalid: false,
  readOnly: false,
  size: 'md',
})
const emit = defineEmits<{ change: [value: string | null] }>()
const uid = useId()
const browserLanguage = ref(undefined as string | undefined)
const draft = ref(monthDraft(props.value !== undefined ? props.value : props.defaultValue))
const typed = ref('')
const reported = ref(
  monthFieldValue(monthDraft(props.value !== undefined ? props.value : props.defaultValue)) ?? '',
)
const field = useTemplateRef<HTMLElement>('field')
const say = computed(() => props.messages ?? { empty: 'Empty' })
const language = computed(() => props.locale ?? browserLanguage.value ?? 'en-US')
const fieldOptions = computed(() => ({ locale: language.value, parts: ['year', 'month'] as const }))
const segments = computed(() => fieldSegments(draft.value, fieldOptions.value))
const current = computed(() => monthFieldValue(draft.value))
const fieldInvalid = computed(
  () => props.invalid || monthOutOfBounds(current.value, { min: props.min, max: props.max }),
)
const commit = computed(() => (next: ReturnType<typeof monthDraft>): void => {
  draft.value = next
  const after = monthFieldValue(next)
  if ((after ?? '') !== reported.value) {
    reported.value = after ?? ''
    emit('change', after)
  }
})
const segmentName = computed(() => (type: string): string => {
  try {
    return new Intl.DisplayNames(language.value, { type: 'dateTimeField' }).of(type) ?? type
  } catch {
    return type
  }
})
const moveSegment = computed(() => (from: EventTarget | null, step: number): void => {
  if (!(from instanceof HTMLElement)) return
  const all = [
    ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
  ]
  all[all.indexOf(from) + step]?.focus()
})
const segmentKeys = computed(
  () =>
    (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
      if (segment.type === 'literal') return
      if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
        event.preventDefault()
        typed.value = ''
        moveSegment.value(
          event.currentTarget,
          (event.key === 'ArrowRight') ===
            (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
            ? 1
            : -1,
        )
        return
      }
      if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
      const editable = !props.disabled && !props.readOnly
      if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
        event.preventDefault()
        typed.value = ''
        if (editable)
          commit.value(
            stepSegment(
              draft.value,
              segment.type,
              event.key === 'ArrowUp' ? 1 : -1,
              fieldOptions.value,
            ),
          )
        return
      }
      if (event.key === 'Backspace' || event.key === 'Delete') {
        event.preventDefault()
        typed.value = ''
        if (!editable) return
        if (draft.value[segment.type] === undefined) moveSegment.value(event.currentTarget, -1)
        else commit.value(eraseSegment(draft.value, segment.type, fieldOptions.value))
        return
      }
      if (event.key.length !== 1) return
      event.preventDefault()
      if (editable)
        ((key: string): void => {
          const next = typeIntoSegment(
            draft.value,
            segment.type,
            typed.value,
            key,
            fieldOptions.value,
          )
          typed.value = next.typed
          commit.value(next.draft)
          if (next.advance) moveSegment.value(event.currentTarget, 1)
        })(event.key)
    },
)
const segmentInput = computed(
  () =>
    (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
      event.preventDefault()
      if (segment.type === 'literal' || !(!props.disabled && !props.readOnly)) return
      const data = (event as InputEvent).data ?? ''
      for (const key of data) {
        const next = typeIntoSegment(
          draft.value,
          segment.type,
          typed.value,
          key,
          fieldOptions.value,
        )
        typed.value = next.typed
        commit.value(next.draft)
        if (next.advance) {
          moveSegment.value(event.currentTarget, 1)
          break
        }
      }
    },
)
const effect1 = () => {
  browserLanguage.value = globalThis.navigator?.language
}
onMounted(effect1)
const effect2 = () => {
  props.value !== undefined &&
    (props.value !== null || current.value !== null) &&
    ((draft.value = monthDraft(props.value)),
    (reported.value = monthFieldValue(monthDraft(props.value)) ?? ''))
}
watch(() => props.value, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'MonthInput',
    element: () => field.value,
    state: () => ({
      value: current.value ?? '',
      disabled: props.disabled,
      invalid: fieldInvalid.value,
      readonly: props.readOnly,
    }),
    actions: {
      set: {
        argument: 'text',
        run: (value) =>
          (() => {
            if (props.readOnly) throw new Error('The field is read-only.')
            commit.value(monthDraft(agentMonth(value, { min: props.min, max: props.max })))
          })(),
      },
      clear: () =>
        (() => {
          if (props.readOnly) throw new Error('The field is read-only.')
          commit.value({})
        })(),
    },
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <div
    ref="field"
    :class="styles.field"
    role="group"
    :id="id"
    :aria-label="ariaLabel"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-disabled="disabled ? 'true' : undefined"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="fieldInvalid ? '' : undefined"
    :data-readonly="readOnly ? '' : undefined"
    data-member="month-input"
  >
    <!-- segments -->
    <div :class="styles.segments">
      <template v-for="(segment, at) in segments" :key="`month-${segment.type}-${at}`">
        <!-- separator -->
        <span v-if="segment.type === 'literal'" :class="styles.separator" aria-hidden="true">
          {{ segment.text }}
        </span>
        <!-- segment -->
        <div
          v-else
          :class="styles.segment"
          role="spinbutton"
          :id="`${uid}-month-${segment.type}`"
          :aria-label="segmentName(segment.type)"
          :aria-labelledby="
            ariaLabelledby ? `${ariaLabelledby} ${uid}-month-${segment.type}` : undefined
          "
          :aria-describedby="ariaDescribedby"
          :aria-valuenow="segment.placeholder ? undefined : segment.value"
          :aria-valuemin="segment.min"
          :aria-valuemax="segment.max"
          :aria-valuetext="segmentValueText(segment, language, say.empty)"
          :aria-required="ariaRequired ? 'true' : undefined"
          :aria-readonly="readOnly ? 'true' : undefined"
          :aria-disabled="disabled ? 'true' : undefined"
          :aria-invalid="fieldInvalid ? 'true' : undefined"
          :contenteditable="!disabled && !readOnly ? 'true' : undefined"
          :inputmode="segment.type === 'dayPeriod' ? undefined : 'numeric'"
          spellcheck="false"
          :tabindex="disabled ? undefined : '0'"
          :data-segment="segment.type"
          :data-placeholder="segment.placeholder ? '' : undefined"
          :data-disabled="disabled ? '' : undefined"
          @focus="typed = ''"
          @keydown="segmentKeys($event, segment)"
          @beforeinput="segmentInput($event, segment)"
        >
          {{ segment.text }}
        </div>
      </template>
    </div>
    <input
      v-if="name !== undefined"
      type="hidden"
      :name="name"
      :value="current ?? ''"
      :disabled="disabled ? true : undefined"
    />
  </div>
</template>
